const p=text=>`<p>${text}</p>`;
const s=(id,title,body)=>({id,title,body});
const ul=items=>`<ul>${items.map(x=>`<li>${x}</li>`).join('')}</ul>`;
const a=(href,label)=>`<a href="${href}">${label}</a>`;
const box=(title,body)=>`<div class="journal-callout" role="note"><h3>${title}</h3>${body}</div>`;
export function journalSections(path,o){
 const content={
 '/guides/website-repair-or-redesign/':[
  s('start','Begin with the failure, not the age of the site',p('An older website does not automatically need replacing, and a recent one can still make a customer’s next step difficult. Start with the task that is failing: understand the service, check its boundaries, find the right information or make an inquiry. Write down what should happen and what actually happens before choosing a new design.')+p('For a Buffalo or Erie County service business, that task may include checking an actual delivery area, a booking requirement or which jobs the business accepts. Those facts can reveal a small content gap or a larger change in the service. A new town name or a different visual style, by itself, does not establish the need for another page or a rebuild.')+p(`This is the decision before the project. If you need help documenting the failure, use the ${a('/guides/website-audit-checklist/','audit checklist')}; if a redesign is already justified, move to the ${a('/guides/website-redesign-brief/','redesign brief')}.`)),
  s('keep','Keep what already does the job',p('Keep the current site when its important visitor tasks work, its content matches the business and the ownership and operating arrangements are sound. A clear, maintainable site does not need a new project simply because another design is fashionable.')+p('Record what is worth retaining: accurate service copy, useful URLs, licensed images, recognizable identity, working forms and client-owned accounts. Also identify who can edit, export and recover the site. If those answers are missing, mark them as unresolved; do not assume that either a patch or a rebuild removes the risk.')+p('No new project is a valid decision. Keep an identified next review trigger, such as a changed service, a recurring visitor problem or an editing need the current setup cannot support.')),
  s('contained','Choose a small fix when the boundary is known',p('A correction is a useful candidate when the affected component is known, the platform and access are supported, a recoverable version exists and the completion test is specific. Correcting an approved label or retaining an inquiry choice may fit; an unknown failure across several external tools needs diagnosis first.')+ul(['Name the page or component that changes and what stays useful.','Check the actual stack, delegated permissions and any provider dependency before agreeing the job.','Describe how the original failing task will be retested, including nearby behavior.','Keep any remaining issue and its owner visible instead of calling the whole site fixed.'])+p('Source-code delivery does not imply arbitrary WordPress repairs, emergency recovery or security incident work. Existing-site work is accepted only after a fit and access review.')),
  s('owned','Two small repairs to try before a rebuild',box('Illustrative examples',`<ol><li><strong>A broken inquiry route.</strong> A garden-care page sends every button to the home page. Point the estimate button to the correct form, preserve the selected service and check the phone and keyboard path.</li><li><strong>An unclear offer.</strong> A repair service mixes included work and exclusions in one list. Separate them so a customer can tell whether the job fits before asking for a quote.</li></ol>`)+p(`Both examples assume the existing site and access support a small change. For an actual studio-owned implementation record, see the ${a('/assets/buyer-packs/owned-audit-two-fixes','two-fix example')}; it does not report client outcomes.`)),
  s('rework','When broader changes or a rebuild make sense',p('Rework can make sense when the existing system remains suitable but its content or page structure no longer explains the business. A rebuild becomes a candidate when agreed requirements cannot be met sensibly in that system. Establish which constraint is real before selecting a new platform; a visual preference and an operational limit are different reasons for change.')+box('Hypothetical scenario — not a client project',p('A service business now needs several distinct service journeys and frequent publishing by a nontechnical editor. Its current one-page static setup has no editing workflow that meets those requirements. First check whether supported changes to the current setup could provide the needed structure and editing. If they cannot, scope a rebuild with retained content, useful URLs, account ownership and migration checks. This scenario does not imply a quoted cost, saving or completion date.'))+p('Changing the platform creates work of its own: content transfer, redirects where needed, form and tool checks, editing training and a recovery route. Include those responsibilities in the comparison; a new design does not automatically complete them.')),
  s('compare','Compare the approved scope and the risk left behind',p('Ask each proposed approach to answer the same question: what visitor task will work at acceptance, which assets and accounts remain useful, what must change and what is still unresolved? Compare the affected pages, provider costs, required inputs and retest. The smallest useful change is the one supported by that evidence, not necessarily the smallest quoted line item.')+p(`The ${money(o.audit_sprint.one_time_price)} ${a('/services/website-audit/','Audit &amp; Fix Sprint')} is one finite option for an eligible supported site: a full baseline and up to two agreed small fixes in total on a supported site with up to 12 marketing pages. It is not a general repair price or a promise to fix every finding. Current ${a('/services/web-design/','website build scopes')} are alternatives when the agreed job requires them, not automatic recommendations for an older site.`)+p(`Use the ${a('/guides/website-project-cost/','budget guide')} for cost components rather than a guessed local repair rate. Actual dates depend on ready inputs, access, reviews, tool fit and capacity; the proposal records the agreed schedule.`)),
  s('worksheet','Make the decision visible before commissioning work',p(`Complete the ${a('/assets/guides/website-repair-or-redesign-worksheet.csv','repair-or-redesign decision worksheet')}. Its six columns record the problem, evidence, content and accounts to keep, platform and access, a small fix with its checks, and your decision. One fictional example shows how to fill it in; use the blank row for your own website.`)+p('Choose one next step: keep the site and record a review trigger; agree a small correction; diagnose a wider unknown; or prepare a rework/rebuild brief. If the necessary access or facts are unavailable, leave the decision open and name the input needed. This is a decision record, not an automated recommendation.'))
 ],
 '/guides/website-care-versus-seo/':[
  s('short-answer','Start with the problem, not the subscription',p('Website care keeps an agreed website and its existing tools dependable: correct supplied details, check important paths and record unresolved issues. Search work asks whether the right page answers a useful customer question, then improves that answer and checks what changed. A broken contact link can affect both, but it is still one correction.')+p('Neither label tells you how much implementation is included. Ask which site, systems, tasks and checks the agreement covers. A supported website with occasional updates may need care; a site with a specific content gap may need a finite improvement or a plan with an agreed search priority. A retainer is optional.')),
  s('compare','Compare tasks you can inspect',`<div class="journal-table-wrap" role="region" tabindex="0" aria-label="Different starting points, one clear work record"><table><caption>Different starting points, one clear work record</caption><thead><tr><th scope="col">Question</th><th scope="col">Care task</th><th scope="col">Search or content task</th></tr></thead><tbody><tr><th scope="row">Are the details correct?</th><td>Publish approved hours, contact details or links in existing components.</td><td>Check whether the service explanation answers the intended customer question.</td></tr><tr><th scope="row">What is being checked?</th><td>The covered site, form and known workflow, with dates and access limits.</td><td>The selected page, intent, factual copy and relevant search evidence when available.</td></tr><tr><th scope="row">What marks completion?</th><td>The agreed correction works, affected paths are checked and unresolved issues are recorded.</td><td>The approved page change and links are verified. Traffic or inquiry effects remain a separate observation.</td></tr><tr><th scope="row">What is not implied?</th><td>Unlimited changes, unsupported-system repair or continuous human monitoring.</td><td>Unlimited articles, link quotas, rankings or AI-search inclusion.</td></tr></tbody></table></div>`),
  s('situations','Three situations, three useful next steps',box('Illustration: changed contact hours',p('A business supplies a new schedule. Update the agreed contact section and related links as one small-change batch, inspect the phone layout and record the approved wording. This is a maintenance task; calling it an SEO campaign adds no useful definition.'))+box('Illustration: an unclear service page',p('A visitor cannot tell which repairs a business handles. Agree the page, approved service boundaries and next action. Revise that explanation, check the links and layout, then decide what actual page or inquiry evidence to observe. This may use one complete content improvement; a ranking increase is not a completion test.'))+box('Illustration: the problem is still unclear',p(`If you do not yet know what is failing, a finite ${a('/services/website-audit/','audit and agreed fixes')} can establish a baseline and finish a small agreed correction. It need not become a subscription. Use the ${a('/guides/website-audit-checklist/','audit checklist')} to describe the problem before choosing.`))),
  s('owned-change','Keep a simple record',p('For each month, write down the problem, the agreed change, the affected page, what was tested and what remains to do. Keep actual search or inquiry results separate from the fact that work was completed.')+p(`Use the ${a('/assets/guides/website-care-versus-seo-worksheet.csv','care-or-SEO decision worksheet (CSV)')} to choose the work you need.`)),
  s('plans','Compare the monthly options',p(`Keep Running is ${money(o.plans.keep_running.monthly_price)}/month for checks and one group of supplied updates. Improve is ${money(o.plans.improve.monthly_price)}/month for that care plus research and ${o.plans.improve.priorities} complete improvement${o.plans.improve.priorities===1?'':'s'}. Grow is ${money(o.plans.grow.monthly_price)}/month for care, deeper research, ${o.plans.grow.priorities} connected improvements and one small item made from approved content.`)+p(`An improvement can be a service page, guide or another agreed task; it does not always mean a new page. Compare the ${a('/services/website-care/','full allowances and exclusions')}. If no useful work is agreed, the next invoice pauses. Historic prepaid rights are described in ${a('/payments/#annual-terms','the payment terms')}.`)),
  s('costs','Check setup and ongoing costs',p(`Monthly service is optional; an eligible existing site needs the ${money(o.baseline.one_time_price)} setup review only if no usable baseline exists. See ${a('/pricing/#after-launch','current plan prices')} and ${a('/pricing/#payments','billing and cancellation terms')}.`)),
  s('before-buying','Ask what the next receipt will contain',ul(['What exact problem and affected page or tool are we agreeing to change?','Is this a group of supplied updates, a main improvement, Grow’s small reuse task or a separate project?','Which systems, accounts and provider costs are included?','Who supplies the facts, approves the work and owns the accounts?','Which test establishes completion, and which result still needs observation?','What happens if access is missing, no useful work is ready or the accepted task is delayed?'])+p(`A useful receipt records the URL, date, approved task, checks, unresolved dependency and next decision. ${a('/guides/seo-work-and-reporting/','Read the reporting guide')} to distinguish implementation evidence from measured effects.`))
 ],
 '/guides/website-audit-checklist/':[
  s('start','Choose one visitor task first',p('Start with a task that matters: identify the right service, understand its boundaries or send an inquiry. Write what you expected and what happened. “The site feels dated” is a useful concern to explore; “a phone visitor cannot find the service boundary before the contact form” is a testable finding.')+p(`Still deciding whether the site needs a project at all? Use ${a('/guides/website-repair-or-redesign/','the repair-or-redesign decision guide')} before expanding the scope.`)+p(`Use the ${a('/assets/guides/website-audit-checklist.csv','audit checklist (CSV)')} to record what you checked, the result, evidence, any fix and the next check. A blank result means untested. Keep screenshots and records free of passwords, customer messages and other private information.`)),
  s('checklist','Eight areas to inspect',`<div class="journal-table-wrap" role="region" tabindex="0" aria-label="A practical first pass; the download provides individual tests"><table><caption>A practical first pass; the download provides individual tests</caption><thead><tr><th scope="col">Area</th><th scope="col">Try this</th><th scope="col">What to record</th></tr></thead><tbody><tr><th scope="row">Buyer journey</th><td>Follow one service question through to its next action.</td><td>The page where the task becomes unclear or stops.</td></tr><tr><th scope="row">Content and intent</th><td>Compare the headline, scope, proof and price explanation with the actual offer.</td><td>A missing fact, unsupported claim or conflicting page purpose.</td></tr><tr><th scope="row">Technical discoverability</th><td>Check the intended page URL, internal links, metadata and declared indexing policy.</td><td>Broken destinations or unintended crawl/index controls. Intentional noindex is a policy decision.</td></tr><tr><th scope="row">Phone and speed</th><td>Repeat the task on a phone; inspect loading and content movement.</td><td>Viewport/device, connection, date and the step affected. Label lab and field evidence separately.</td></tr><tr><th scope="row">Accessibility basics</th><td>Use the main path with a keyboard, visible focus, enlarged text and reduced motion.</td><td>Specific blocked controls or lost content; automated results are only part of the evidence.</td></tr><tr><th scope="row">Forms</th><td>Check labels, useful errors and whether a chosen service survives a retry.</td><td>Separate validation, saved receipt and notification delivery; verify each only when authorized.</td></tr><tr><th scope="row">Ownership and recovery</th><td>Identify the domain, hosting, editing and recovery owners.</td><td>Which accounts, exports and recovery steps were actually inspected.</td></tr><tr><th scope="row">Measurement</th><td>Identify the question, relevant page and available measurement window.</td><td>Source, dates, access gaps and limits on interpreting change.</td></tr></tbody></table></div>`+p('Our website audit records findings across buyer relevance, design, evidence, offer clarity, journeys, accessibility, performance, search and ownership. These eight groups make a home checklist manageable; they do not replace the complete review or constitute accessibility, security or legal certification.')+p(a('/services/website-audit/#review-method','Inspect all review areas and what you receive'))),
  s('priority','Turn a finding into a small correction',p('Explain the practical consequence of each finding. A blocked primary inquiry task is usually more urgent than a minor spacing issue. An unsupported promise may matter even when every automated check passes. Record what is known, what is uncertain and who decides the priority.')+box('An illustrative small agreed fix',p('Finding: a service link leads to an unrelated page. Scope: correct that one destination in the known component. Completion: the link opens the intended page, its label describes the destination and the affected phone/keyboard path works. A full navigation redesign is a different scope.'))+p('Agree the affected area and completion test before editing. Preserve a recoverable version, implement the correction, then repeat the original failing task and check nearby behavior. An automated result is not a substitute for that retest.')),
  s('owned-fixes','An audit finding a business owner can use',box('Illustrative contact-form finding',`<p><strong>Problem:</strong> the form shows success, but the owner cannot find the inquiry.</p><p><strong>Next check:</strong> look for the same controlled test in the form provider’s submission record, then inspect its notification destination.</p><p><strong>Possible fix:</strong> if the record exists and the recipient is an old mailbox, update that recipient with the owner’s approval.</p><p><strong>Finish:</strong> submit one new test, confirm receipt and inbox arrival, then reply to the controlled address. Record anything that remains unverified.</p>`)+p(`This example is hypothetical. The ${a('/assets/buyer-packs/owned-audit-two-fixes','studio’s two-fix record')} shows separate, actual changes to this website. A successful content check does not prove inbox delivery.`)),
  s('access','Use “needs access” when you cannot test',p('Public pages let you inspect copy, links and many layout or keyboard behaviors. Search Console, analytics, form storage, notification logs, account ownership and restore operations may require authorized access. Mark those checks “needs access” with a named owner and next step; do not turn a missing account into a pass or a guessed diagnosis.')+p('A live form test can create a record or send a notification. Agree the test destination and synthetic data before submitting, then distinguish the browser confirmation, stored record and actual delivery. Recovery tests need a safe environment and an agreed rollback procedure.')+p('Real users, assistive technology and physical devices can expose problems a scanner misses. If a task needs specialist investigation, record the boundary and commission the appropriate review instead of promising that a general website audit covers it.')),
  s('finish','Finish with a dated record and the next decision',ul(['Link the original finding and its evidence date.','State the approved fix and the exact changed page or component.','Record the retest method, result, environment and unresolved limitation.','Name the owner of the remaining issue and the next decision.','Keep the accepted scope and paid handoff materials together.'])+p(`Our ${money(o.audit_sprint.one_time_price)} ${a('/services/website-audit/','Audit &amp; Fix Sprint')} covers an eligible supported site with up to 12 marketing pages, a full baseline and up to two agreed small fixes. It does not promise to repair every finding. Search-only questions can start with ${a('/services/seo/','the SEO scope')}; a larger redesign can start with ${a('/guides/website-redesign-brief/','a clear project brief')}. ${a('/contact/','Share the task and evidence')} to discuss fit.`))
 ],
 '/guides/website-project-cost/':[
  s('start-with-scope','A useful price starts with a useful scope',p('If you are comparing web design prices in Buffalo, start by writing down the customer decision your site must support. A solo service business explaining one offer needs a different website from a company with several service lines, a large content library and online booking. A page count helps, but it does not describe all the work.')+p('This guide uses Wonder and Method’s published prices to make the comparison concrete. They are my studio prices, not a Buffalo market average. The examples are estimates for defined work, not completed client projects.')),
  s('two-budgets','What each build includes',p('Every studio website package includes writing, keyword research, on-site SEO, design, two combined feedback rounds, checks before launch, source files and a written handoff. You control the accounts. One initial launch and 30 days of correction for defects against the accepted scope are included.')+p('Launch supports a clear presence with one form and one ready service connection. Focused adds more service detail, two forms, two original guides and up to two ready connections. Signature adds a larger page plan, four original guides and an original animated hero or 3D centerpiece. Guides count within the page allowance; these are scope caps, not targets to fill.')+p(`See ${a('/pricing/#website-packages','the complete package comparison')} for creative assets, handoff and feature limits.`)),
  s('ongoing-costs','Separate the build from the bills that continue',p(`Optional monthly plans are Keep Running ${money(o.plans.keep_running.monthly_price)}, Improve ${money(o.plans.improve.monthly_price)} and Grow ${money(o.plans.grow.monthly_price)}. Hosting, domain, mailbox and form/email charges are paid directly to approved providers. Other services require separate scope and approved costs. One agreed initial website launch is included; monthly service is optional.`)+box('Worked example — assumed costs, not a provider quote',p(`Focused ${money(o.focused_site.public_price)} plus 12 Keep Running invoices at ${money(o.plans.keep_running.monthly_price)} has ${money(o.focused_site.public_price+12*o.plans.keep_running.monthly_price)} of studio service fees. Assume monthly service runs for 12 months from launch, hosting is $20/month for 12 months and all other provider charges total $120. Add $240 hosting and $120 other fees once. Estimated total: ${money(o.focused_site.public_price+12*o.plans.keep_running.monthly_price+240+120)}, before taxes or added scope. These assumed fees must be replaced with actual approved bills.`))+p('Required provider fees are confirmed before you commit. Monthly work must be distinct from launch scope and defect correction; the same work is never charged twice.')+p(`An eligible existing site needs a ${money(o.baseline.one_time_price)} baseline only if no usable one exists. A paid studio build or usable ${money(o.audit_sprint.one_time_price)} Sprint already includes it. Monthly service is optional, not financed website ownership; builds use 50/30/20 written-acceptance milestones.`)),
  s('annual-choice','Check the payment schedule',p('Website payments use 50/30/20 milestones. Monthly service is optional. See '+a('/payments/','payment terms')+'.')),
  s('scope-changers','What changes the budget?',ul(['Additional features or connections beyond the accepted page and feature list.','A large migration, original field research or facts that must be established.','Original photography, full identity redesign or creative production beyond the listed assets.','Additional review rounds, a new direction or extra marketing pages.'])+p('Useful copy for the agreed purposes has no word quota. One initial website launch and the agreed ready-service connections are included. Extra work receives a written scope and price before it begins.')),

  s('compare-quotes','Bring the same brief to each conversation',p('Ask each studio to respond to the same list of pages, supplied content, required features, editing needs, review dates and acceptance checks. Then compare what is included, what is excluded and how a change is priced. Timeline should follow actual inputs and review capacity; a vague rush request is not a reliable schedule.')+box('Before requesting a quote',ul(['Name one customer action the site should make easier.','List the pages and features you actually need.','Identify the content owner and one approver.','Choose an editing approach and record outside bills.','Ask what you receive at handoff and what happens after launch.']))+p(`Use the ${a('/guides/website-redesign-brief/','redesign brief')} to prepare, explore ${a('/services/web-design/','custom web design in Buffalo')}, or ${a('/contact/','send the project details')}.`))
 ],
 '/guides/website-redesign-brief/':[
  s('before-a-redesign','First, confirm that a redesign is the right job',p(`If you have not yet decided what needs to change, ${a('/guides/website-repair-or-redesign/','compare keeping, fixing, reworking and rebuilding the site')}. This brief helps define a redesign after that earlier decision.`)),
  s('decision','Begin with the decision your customer is making',p('“We need a modern website” is a starting feeling, not yet a project brief. A useful brief says who the website is for, what they need to understand and what they should do next. That gives the design a purpose and makes proposals easier to compare.')+p('For a Buffalo or Erie County service business, the next step might be an estimate request, a phone conversation or a project inquiry. Choose a primary action. Explain what a qualified inquiry looks like so that a form can collect useful details without becoming a long application.')),
  s('business','1. Describe the actual business',ul(['What do you sell, and which one or two service lines matter most?','Who is a good fit, and who is outside the scope?','Where do you deliver the service? Distinguish online work, customer visits and a staffed location.','What should a visitor know before contacting you?','Which claims, qualifications and examples can you support?'])+p('Be specific about geography. Serving customers in Amherst or Hamburg does not imply a public office there. If the business works online, say so. Accurate service information is more useful than a list of town names pasted into every paragraph.')),
  s('content','2. Inventory the content before redesigning it',p('List the current URLs, page titles and purpose of each page. Mark what should remain, what needs rewriting and what can be retired. Identify pages that receive valuable inquiries or search visits before merging them.')+p('Collect approved service facts, the jobs you accept, actual delivery areas, contact and opening details, licensed photographs, and evidence you have permission to share. Add recurring customer questions, mark missing material and name the person responsible for approving changes and keeping each fact current. For a seasonal service, for example, the estimate may depend on property type, the actual route and information needed before booking; the business supplies its own operating facts.')+p(`If URLs will change, use the ${a('/guides/website-migration-checklist/','migration checklist')} to map each useful old address to the most relevant new destination.`)),
  s('editing','3. Decide who edits and what the site must do',p('Describe updates in everyday terms: “I change opening hours twice a year,” “our team publishes weekly,” or “prices come from another system.” Those are different requirements. A custom static website may fit infrequent changes; all three studio plans include editable source code and instructions. Agree who will make, check and publish changes, and how often help will be needed.')+ul(['Does the site need only an inquiry form, or does it need booking or payment?','Will people sign in or view private information?','Does data move into a CRM or another service?','Who maintains integrations and pays the provider bills?','What happens if an external service is unavailable?'])+p('Write required features separately from ideas that would be nice later. That protects the initial project from quietly becoming a different product.')),
  s('acceptance','4. Define how the project gets approved',p('Name one approver, input dates and realistic review windows. Agree which pages and forms must work on a phone and with a keyboard. Ask the developer to record how the previous version can be restored. Capture changes in one consolidated list so decisions do not conflict across messages.')+p('Before launch, approval should identify the actual version and destination. After launch, handoff should include paid source, assets and licenses, account ownership, provider renewals, form-data handling and recovery notes. Wonder and Method includes 30 calendar days of correction for defects against accepted scope; later Care or Search is optional.')+box('A brief you can reuse',p(`${a('/assets/downloads/website-redesign-brief.txt','Download the plain-text redesign brief')} and fill it in with your own business facts. It opens in any text editor and can be pasted into a document.`))+p(`Read the ${a('/assets/audit-implementation/illustrative-completed-brief.txt','completed illustrative brief')}—a fictional planning example, not a client project. See ${a('/process/','the studio process')}, compare ${a('/services/web-design/','website scopes')}, then ${a('/contact/','start a conversation')}.`))
 ],
 '/guides/local-seo-profile-eligibility/':[
  s('two-surfaces','Your website and your Business Profile have different jobs',p('Local SEO helps a business explain what it offers and where it serves customers. Your website can give that explanation in detail. A Google Business Profile is a separate product with its own eligibility rules. Having a website or serving Buffalo customers does not by itself make a business eligible for a profile.')+p('Google says local results consider relevance, distance and prominence. Useful website work can make services clearer, but it cannot remove the distance between a searcher and a business. No page edit can promise a particular Maps position. See '+a('https://support.google.com/business/answer/7091','Google’s explanation of local ranking')+'.')),
  s('eligibility','Check eligibility before choosing an address',p('Google generally requires eligible businesses to make in-person contact with customers during their stated hours. Online-only businesses are not eligible for a Business Profile. A service-area business that visits customers may qualify under the applicable rules; a studio delivering all work remotely should not assume that it does. Read '+a('https://support.google.com/business/answer/3038177','Google’s business representation guidelines')+' and its '+a('https://support.google.com/business/answer/13763036','eligibility guidance')+'.')+p('For an eligible business that travels to customers and does not serve them at its address, Google instructs it to hide that address. Service areas should describe actual service, not a collection of desirable search locations. Confirm your situation against '+a('https://support.google.com/business/answer/9157481','Google’s service-area instructions')+' before changing the profile.')+box('How I describe my own studio',p(e(serviceCoverage().statement)+' Our coverage describes online service reach; it does not claim a walk-in office or in-person service. We do not use a virtual-office address to imply otherwise.'))),
  s('pages','Write pages around the services people need',p('Begin with a clear page for each materially different primary service. Explain the customer problem, what is included, what changes the price, where the work is delivered and how to inquire. A redesign prospect and an ongoing SEO prospect have different questions, so they deserve clear paths.')+p('For a Buffalo-area service firm, local detail can be practical: travel boundaries, remote review options, appointment requirements or the information needed for a quote. Use only facts that apply. Copying one page into dozens of town-name variants adds little if the service and evidence are identical.')+p('A useful Erie County service-area page can gather coverage and working arrangements. A separate town page needs a separate reason to exist: genuinely different logistics, service details or supported work examples. A new place name alone is not that reason.')),
  s('sequence','A practical order for local search work',ul(['Verify the business name, contact details, service model and profile eligibility.','Make the primary service pages clear, complete and easy to reach.','Fix broken inquiry paths and misleading location information.','Link useful planning guides to the relevant service, pricing and contact pages.','Measure page-level search visibility and actual inquiry quality before choosing more work.'])),
  s('expectations','Buy a defined improvement, then evaluate it',p('Ask what will change on the website, why that is the next priority and how completion will be checked. “More SEO” is too broad to evaluate. A clearer service explanation, repaired internal link and verified inquiry path are concrete work; their commercial effect still needs measurement.')+p(`Explore ${a('/services/seo/','scoped SEO services for Buffalo businesses')}, read our ${a('/areas/erie-county/','Erie County delivery model')}, or ${a('/contact/','discuss the next useful improvement')}.`))
 ],
 '/guides/seo-work-and-reporting/':[
  s('work','A monthly report should connect work to a decision',p('A list of rankings does not tell you what an SEO service actually did. Useful reporting connects a customer problem, a specific page change, the checks performed and the next decision. Search measurements add context, but they should not replace an inspectable work record.')+p('For a small Buffalo service business, the priority may be modest and valuable: explain a service boundary, improve a confusing inquiry step or make an important page easier to find. A monthly purchase should name the unit of work so both sides can tell when it is complete.')),
  s('keyword-opportunities','How keyword opportunities become useful work',p('Start with the real service, the customer question and the action you want a useful page to support. Keyword research can help identify related searches, difficulty estimates and competing content. Search Console and actual customer questions add evidence about the website and business. Record what is available and label what is missing.')+ul(['Investigate relevant lower-competition terms, existing pages with useful impressions, customer questions and seasonal opportunities.','Check actual search results: are people looking for a service, guide, product, map listing or comparison?','Compare competing pages and identify a truthful useful contribution your business can make.','Group close variants around the same need; improve an existing page when it already fits.','Select the page or action, record why it matters and define what finished work will include.'])+p('Keyword difficulty and search volume are estimates, not ranking probabilities or deadlines. Record the metric source, lookup date and geography; national organic difficulty is not a neighborhood map-ranking estimate. A low score for an irrelevant term is not a good business opportunity.')+p('Your opportunity brief should identify the customer question, business fit, available metrics, result-page observations, preferred URL, approved facts and completion test. '+a('/assets/guides/monthly-seo-opportunity-worksheet.csv','Download the monthly opportunity worksheet')+'. No invented keyword figures are supplied in the example.')),
  s('receipt','What a useful monthly report shows',box('Example only — no client outcome claimed',ul(['Property: an illustrative local service website. Role: website and content implementation. Period: one monthly work cycle.','Problem: visitors cannot tell whether they need a new site or an improvement to an existing one.','Change: revise the existing service page with a clearer fit explanation and one primary inquiry action.','Related fix: add a descriptive internal link from the pricing page.','Checks: compare claims with the accepted scope; test links, keyboard use, mobile layout and form validation.','Measurement: record the implementation date and compare relevant page and inquiry data when available. No uplift is assumed.','Next decision: keep the change, refine an unresolved question or stop if no useful scoped task remains.']))+p('The report should link to the changed page or clearly identify the section. It should also name anything still waiting for access or a decision. If analytics access is missing, the report should say so instead of presenting guessed results.')+p(`For an actual owned example, inspect ${a('/assets/buyer-packs/owned-audit-two-fixes','the dated audit-and-two-fix packet')}. To choose the task before interpreting its report, use ${a('/guides/website-care-versus-seo/','the care-versus-SEO comparison')}.`)),
  s('metrics','Read search data in context',p('Search Console reports clicks; impressions (how often a result was shown); click-through rate (the share of those impressions that led to a click); and average position (the average result position). Filter by the page, query, country, device and period relevant to the question. A site-wide average can hide what happened to one service page. Google explains these measures in its '+a('https://support.google.com/webmasters/answer/7576553','Performance report documentation')+'.')+p('A comparison also needs context: the dates, what changed, whether the sample is small and whether seasonality or other activity could explain the difference. A few additional clicks do not establish that one edit caused growth. Keep observations separate from interpretations.')+p('Qualified inquiries add another view. Record whether the person needs the service you offer, is within the delivery scope and can move toward a real conversation. Avoid putting names, email addresses or message contents into a public SEO report.')),
  s('scope','Choose the amount of work you can use',p(`Keep Running at ${money(o.plans.keep_running.monthly_price)}/month covers agreed checks and a related batch of updates using supplied content. Improve at ${money(o.plans.improve.monthly_price)}/month adds a monthly keyword opportunity brief, ${o.plans.improve.priorities} complete improvement${o.plans.improve.priorities===1?'':'s'} and quarterly topic-map refresh. Grow at ${money(o.plans.grow.monthly_price)}/month adds deeper keyword/competitor research, ${o.plans.grow.priorities} connected improvements, a rolling 90-day plan and one small promotional reuse task.`)+p(`For example, Improve could rewrite a service page from approved facts, including relevant metadata, internal links, publication and contact-path checks. Grow could pair that page with a distinct buyer guide and reuse approved content in a simple branded graphic/caption or a newsletter excerpt of up to 150 words. The reuse task is additional; a new full creative concept or email campaign setup is separate from that small task. Agree useful work before the cycle starts. ${a('/services/website-care/','Read the plan limits and coverage')} and ${a('/pricing/#payments','payment and cancellation terms')}.`)),
  s('campaigns','Plan the next useful work',p('A rolling 90-day plan connects this month’s work with the next customer questions to answer. Update it when services or evidence change; it is a planning horizon, not a promise of search results.')+p('Grow also includes one small piece made from approved content: a simple graphic in up to three sizes with a caption, or a newsletter excerpt up to 150 words. This is additional to its two main improvements. Public posting or sending needs explicit approval; a new creative concept or email setup needs separate scope.')),
  s('time','How long should you wait?',p('Implementation can have a clear completion date; search impact does not have a guaranteed date. Start with a baseline and a measurement window suited to the available volume. If the site is new, unindexed or receives very little relevant traffic, a short comparison may not support a meaningful conclusion.')+p('Ask the provider to explain uncertainty and the next action. A good decision may be to collect more data, improve a different customer question or stop recurring work until a useful task is available. Promises of guaranteed Google positions or guaranteed AI citations should not substitute for a defined service.')+p(`Read ${a('/services/seo/','the full SEO scope')}, compare ${a('/pricing/','current pricing')}, inspect ${a('/work/','the studio work')}, or ${a('/contact/','discuss your existing website')}.`))
 ],
 '/guides/website-migration-checklist/':[
  s('inventory','Treat a redesign as a move when addresses change',p('A new website can look finished while important old links lead nowhere. If page addresses, domains, content structure or hosting change, plan the move alongside the design. The aim is to preserve useful paths for customers and give search engines clear signals about the new locations. No checklist can guarantee that traffic stays unchanged.')+p('Begin with an inventory of current URLs, downloads, forms and external integrations. Identify the pages that receive meaningful search visits, customer inquiries or links. Keep a recoverable copy of the existing site and a record of who controls the domain, hosting and email settings.')),
  s('map','Build an old-to-new URL map',p('For each important old URL, record the most relevant new destination and the reason for the decision. Keep an address unchanged when that serves the new structure. If content is combined, map the old page to the new page that answers the same need. Do not send every retired service or article to the home page.')+p('Google recommends mapping URLs and implementing appropriate permanent redirects for a site move. It also describes temporary search fluctuations while a move is processed. Use its '+a('https://developers.google.com/search/docs/crawling-indexing/site-move-with-url-changes','site-move documentation')+' for the technical details.')+box('Make the mapping explicit',p(`${a('/assets/downloads/website-url-map.csv','Download the URL map worksheet (CSV)')}. It starts with three example rows you can replace. Record the old URL, new URL, decision, reason, person responsible and what to check. These are invented examples, not a client migration.`))),
  s('before','Before changing the live site',ul(['Check the new pages, titles, descriptions, internal links and canonical addresses.','Confirm that redirects lead directly to the intended destination and do not create loops.','With permission, submit a clearly labeled test. Verify acceptance, any retained record and the owner’s delivery path.','Test key pages and navigation on narrow screens and with a keyboard.','Check important downloads, booking links and every included or separately scoped integration.','Record the approved version, release destination and rollback procedure.','Agree whether indexing is enabled or intentionally held, and verify both page settings and server instructions.'])+p('Keep email settings separate from website hosting changes. A domain can provide both services, but moving a website does not require casually replacing unrelated mail records. Name the exact DNS changes before applying them.')),
  s('launch','At launch, verify what customers actually reach',p('Open the public addresses after deployment, including both the preferred domain and any alternate host. Check representative old URLs, the main service pages, contact, downloads and a deliberately missing page. A missing page should return a real 404 status with a useful route back.')+p('Confirm the form works from the public website, not only in a local preview. Keep a test reference and remove test data using the documented process. Record any delivery uncertainty. Where the agreed system retains submissions, check that the owner can recover the test if its notification is delayed. Otherwise, document the actual receipt and recovery arrangement.')),
  s('after','Review the move over time',p('After an intentionally indexable launch, use the available search tools to review crawling, indexing and page-level performance. Compare the same kinds of traffic over useful periods and investigate patterns instead of reacting to one day. If indexing is still paused, do not interpret the absence of rankings as a content result.')+p('A migration can range from a few renamed pages to a major platform move. Extensive migration, WordPress remediation and new integrations are separately scoped work; this guide does not promise a universal rescue service.')+p(`Prepare with the ${a('/guides/website-redesign-brief/','redesign brief')}, explore ${a('/services/web-design/','website design')}, review ${a('/services/seo/','SEO improvements')}, or ${a('/contact/','discuss the actual move')}.`))
 ],
 '/guides/custom-website-or-template/':[
  s('fit','Both approaches can work. Fit is the question.',p('A template offers an existing visual and structural starting point. A custom website can organize the experience around the business’s particular story and customer journey. Neither label tells you, by itself, whether a site is clear, fast, accessible or easy to maintain.')+p('For a Buffalo small business choosing a website, begin with content and operations. What must customers understand? How often will the site change? Who will edit it? What can you invest in the build and in maintaining it? Those answers matter more than how many effects appear in a demo.')),
  s('compare','Compare the same customer journey',`<div class="journal-table-wrap" role="region" tabindex="0" aria-label="Questions to ask of either approach"><table><caption>Questions to ask of either approach</caption><thead><tr><th scope="col">Decision</th><th scope="col">Template starting point</th><th scope="col">Custom direction</th></tr></thead><tbody><tr><th scope="row">Service story</th><td>Does the existing page structure fit your content?</td><td>Can a tailored structure explain the service more clearly?</td></tr><tr><th scope="row">Editing</th><td>Which changes does the included editor support?</td><td>Does the owner need a developer or a separately included page editor to make changes?</td></tr><tr><th scope="row">Distinctive design</th><td>How much can be changed without fragile overrides?</td><td>Which original design decisions matter to the customer?</td></tr><tr><th scope="row">Ongoing cost</th><td>What subscriptions, add-ons and platform limits apply?</td><td>What hosting, provider and maintenance costs remain?</td></tr><tr><th scope="row">Handoff</th><td>What can you export or move to another provider?</td><td>Which paid source, assets and operating notes do you receive?</td></tr></tbody></table></div>`+p('Try a small comparison before committing: use the same service headline, explanation, proof and inquiry fields in each proposed structure. Walk through it on a phone. Notice where the content feels forced, where the next step disappears and which changes require workarounds.')),
  s('template','When a template may be a sensible starting point',p('A template may fit when the service is straightforward, the existing layout supports the content and the team values a familiar editing environment. It can reduce some initial design decisions. Still check the actual plan limits, recurring costs, access controls and export options.')+p('Do not assume that buying a template includes content strategy, copy, photography, migration, form delivery or accessibility review. Those responsibilities exist even when the layout is already drawn. Agree who completes and verifies them.')),
  s('custom','When custom work is useful',p('Custom work may fit when your service story, design or inquiry process needs a structure that a template cannot easily support. Agree what will be designed and built before choosing a package.')+p(`Studio builds are ${money(o.launch_site.public_price)}, ${money(o.focused_site.public_price)} and ${money(o.signature_site.public_price)} for up to 6, 15 and 30 marketing pages. Each includes writing, design, launch and source files. Future changes require coding skills, a developer or optional care; there is no built-in drag-and-drop editor. ${a('/pricing/#website-packages','Compare the full packages')} and tell me how often you need to edit.`)),
  s('quality','Judge the finished experience',ul(['Can a new visitor explain what the business does and who it serves?','Is the primary next step easy to find and complete on a phone?','Can the main journey be used with a keyboard and reduced motion?','Are prices or scope boundaries understandable?','Does the form accept the inquiry and can the owner find it and reply?','Can the owner maintain the site and recover it when needed?'])+p('A useful website explains the offer and lets people complete the next step. Motion can add character when it supports that job; it should pause cleanly and respect reduced-motion preferences.')+p(`Explore ${a('/work/','studio work and explorations')}, read ${a('/services/web-design/','the custom website scope')}, compare ${a('/guides/website-project-cost/','website budget examples')}, or ${a('/contact/','talk through the fit')}.`))
 ]};
 return practicalGuideSections(path,[...(content[path]||ongoingGuideSections(path,o)||searchGuideSections(path,o)||[]),...searchGuideAdditions(path),...guideAdditions(path,o)],o);
}

const readableDate=value=>new Date(value+'T12:00:00Z').toLocaleDateString('en-US',{month:'long',day:'numeric',year:'numeric',timeZone:'UTC'});
const guideDiagramAlts={
 'google-visibility-flow':'Keep private pages excluded. For public pages, check discovery, indexing and relevance; assess Maps eligibility separately. Search placement is not guaranteed.',
 'contact-form-flow':'Trace one authorized test through submission, receipt, notification, inbox and reply. Investigate the first missing step; a success message alone does not prove delivery.',
 'service-area-decision':'Confirm coverage and a distinct customer question. Use an existing page when it answers the question; create and maintain a separate page only when useful.',
 'maintenance-cycle':'Choose important website tasks, check them, record results, agree corrections and retest. Set the schedule and responsibilities for your actual site.',
 'contractor-inquiry':'Explain accepted work, show real evidence, confirm coverage, collect job details and acknowledge the request. A request is not a quote or confirmed appointment.',
 'care-versus-seo':'Care keeps the site working; search work improves its answer to a customer question. Both end with a verified, dated change record, not promised growth.',
 'audit-checklist':'Question, evidence, priority, agreed small fix, retest and dated record. Obtain missing account access before continuing checks that need it.',
 'repair-or-redesign':'Confirm the task and access. Keep what works, fix a known small problem, or assess broader changes and rebuilding. Missing access pauses the decision.'
};
const guideCardDescriptions={
 'website-maintenance-cost':'Separate hosting and tool bills from maintenance work, then build a realistic yearly website budget.',
 'website-launch-checklist':'Check content, forms, phone layouts and account access before launch, then test the public website.',
 'ai-website-or-custom':'Test an AI website draft for accurate content, working forms, editing access and ownership before committing.',
 'website-not-showing-on-google':'Check whether Google has indexed your page, then investigate search relevance and Maps eligibility separately.',
 'contact-form-not-working':'Send one test and check submissions, notification settings, spam and replies to find the missing step.',
 'service-area-pages':'Decide whether your customers need a separate area page or one clear explanation of service coverage.',
 'website-maintenance-checklist':'Keep business details, contact paths and account access working with a practical schedule and maintenance log.',
 'contractor-website-checklist':'Explain accepted jobs, real project evidence, service coverage and what customers should send for an estimate.',
 'website-project-cost':'Compare website packages, local quotes and outside bills, with scope and payment schedules made clear.',
 'website-redesign-brief':'Prepare the customer goals, page list, business facts and editing responsibilities needed for a useful quote.',
 'local-seo-profile-eligibility':'Check Google Business Profile eligibility and describe your real services and coverage without inventing an office.',
 'seo-work-and-reporting':'Connect search research to a completed website improvement, then separate the work record from measured results.',
 'website-migration-checklist':'Map old page addresses, plan matching redirects and test forms before and after moving your website.',
 'custom-website-or-template':'Compare custom design and templates around your content, customer journey, editing needs, ownership and ongoing costs.',
 'website-care-versus-seo':'Match routine updates and search improvements to the problem before choosing monthly help or a finite project.',
 'website-audit-checklist':'Follow a customer task, record where it fails and agree a small correction with a clear retest.',
 'website-repair-or-redesign':'Decide whether to keep your site, fix a small problem, rework its content or consider rebuilding.'
};
const guideThumbnail=item=>'/assets/guides/'+item.path.split('/').filter(Boolean).at(-1)+'-card';
const articleFigure=item=>item.diagram?`<figure class="journal-hero journal-diagram"><img src="/assets/guides/${item.image}.svg" width="360" height="${item.imageHeight}" alt="${e(guideDiagramAlts[item.image])}" loading="lazy" decoding="async"></figure>`:`<figure class="journal-hero"><img src="${guideIllustration(item)}-1200.webp" srcset="${guideIllustration(item)}-640.webp 640w, ${guideIllustration(item)}-1200.webp 1200w" sizes="(max-width:700px) calc(100vw - 40px), (max-width:1000px) 62vw, 760px" width="1200" height="800" alt="${e(guideIllustrationAlt(item))}" loading="lazy" decoding="async"></figure>`;
export function journalCard(item,{headingLevel=3,layout='related',eager=false}={}){
 const slug=item.path.split('/').filter(Boolean).at(-1),description=guideCardDescriptions[slug];
 if(!description)throw Error(`Missing guide card description: ${slug}`);
 if(layout==='index')return `<article class="journal-card journal-card-text"><div><h${headingLevel}><a href="${item.path}">${e(item.title)}</a></h${headingLevel}><p class="journal-card-description">${e(description)}</p></div></article>`;
 return `<article class="journal-card"><span class="journal-card-image"><img src="${guideThumbnail(item)}-480.webp" srcset="${guideThumbnail(item)}-480.webp 480w, ${guideThumbnail(item)}-720.webp 720w, ${guideThumbnail(item)}-1080.webp 1080w" sizes="(max-width:767px) calc(100vw - 40px), 406px" width="1080" height="720" alt="" loading="${eager?'eager':'lazy'}" decoding="async"></span><div><p class="eyebrow">${item.category}</p><h${headingLevel}><a href="${item.path}">${e(item.title)}</a></h${headingLevel}></div><p class="journal-card-description">${e(description)}</p></article>`;
}
export function journalIndex(items){const groups=[{id:'diagnose',title:'Solve a website problem',paths:['website-not-showing-on-google','contact-form-not-working']},{id:'choose',title:'Choose your next project',paths:['website-repair-or-redesign','custom-website-or-template','website-project-cost','ai-website-or-custom']},{id:'plan',title:'Plan the work',paths:['service-area-pages','website-redesign-brief','website-audit-checklist','website-migration-checklist','contractor-website-checklist','website-launch-checklist']},{id:'care-search',title:'Understand care and search',paths:['website-care-versus-seo','seo-work-and-reporting','local-seo-profile-eligibility','website-maintenance-checklist','website-maintenance-cost']}];let firstCard=true;return `<header class="page-intro"><p class="eyebrow">Website guides</p><h1>Practical website<br>and SEO guides.</h1><p class="lede">Clear explanations, examples and worksheets for the decisions around your website. Written for service businesses in Buffalo, Erie County and across ${e(serviceCoverage().region)}.</p></header><nav class="page-jump" aria-label="Guide topics">${groups.map(g=>'<a href="#'+g.id+'">'+g.title+'</a>').join('')}</nav>${groups.map(g=>'<section class="journal-group" id="'+g.id+'"><h2>'+g.title+'</h2><div class="journal-index-list">'+items.filter(item=>g.paths.some(slug=>item.path==='/guides/'+slug+'/')).map(item=>{const card=journalCard(item,{headingLevel:3,layout:'index',eager:firstCard});firstCard=false;return card;}).join('')+'</div></section>').join('')}`;}
